if (size <= 0) {
    return nullptr;
}
auto cmp = [](TreeNode* a, TreeNode* b) { return a->freq > b->freq; };
std::priority_queue<TreeNode*, std::vector<TreeNode*>, decltype(cmp)> pq(cmp);
for (int i = 0; i < size; ++i) {
    TreeNode* node = new TreeNode;
    node->value = values[i];
    node->freq  = freqs[i];
    node->left = node->right = nullptr;
    pq.push(node);
}
while (pq.size() > 1) {
    TreeNode* left  = pq.top(); pq.pop();
    TreeNode* right = pq.top(); pq.pop();
    TreeNode* parent = new TreeNode;
    parent->value = -1;               // marker for internal node
    parent->freq  = left->freq + right->freq;
    parent->left  = left;
    parent->right = right;
    pq.push(parent);
}
return pq.top();

